# Add missing functions if necessary

def identity(x):
    return x

def complement(fn):
    return lambda *args, **kwargs: not fn(*args, **kwargs)

def flip(fn):
    return lambda *args, **kwargs: fn(*kwargs, *args)

def thread_first(fn):
    return lambda *args, **kwargs: fn(*args, **kwargs)

def countby(key):
    return lambda coll: {k: len(list(filter(key.__eq__, coll))) for k in set(map(key, coll))}

